// Cloudflare Worker entry: wraps the OpenNext handler.
// Only https://qactions.com/techimpact is indexable; the *.workers.dev host and
// local previews answer with noindex (next.config `headers` host conditions
// are not applied by OpenNext, so this is enforced here).
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

const PUBLIC_HOST = /^(www\.)?qactions\.com$/;

export default {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    const res: Response = await handler.fetch(request, env, ctx);
    if (PUBLIC_HOST.test(new URL(request.url).hostname)) return res;
    const out = new Response(res.body, res);
    out.headers.set('X-Robots-Tag', 'noindex, nofollow');
    return out;
  },
};
